        "content": "Script ini merekonstruksi TLS key log dari dua share, membaca observation QUIC yang sudah didekripsi, menyambung firmware, memilih arsip/transaksi yang memenuhi checkpoint dan receipt, lalu membuka final seal.\n\n```python\n#!/usr/bin/env python3\n\"\"\"Reproduce the evidence chain and recover the authenticated final artifact.\"\"\"\nimport base64\nimport hashlib\nimport json\nimport re\nimport sqlite3\nimport subprocess\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent\nOBJECTS = ROOT / \"http_objects\"\nPCAP = ROOT / \"the-quiet-divide\" / \"the-quiet-divide.pcap\"\n\n\ndef load_json(path):\n    return json.loads(Path(path).read_text())\n\n\ndef canonical(obj):\n    return json.dumps(\n        obj, sort_keys=True, separators=(\",\", \":\"), ensure_ascii=True,\n        allow_nan=False,\n    ).encode(\"ascii\")\n\n\ndef sha256(raw):\n    return hashlib.sha256(raw).hexdigest()\n\n\n# The two escrow slots are bytewise XOR shares of a TLS key log.\nshare_a = load_json(OBJECTS / \"escrow\")\nshare_b = load_json(OBJECTS / \"escrow(2)\")\nassert share_a[\"linked_observation_sha256\"] == share_b[\"linked_observation_sha256\"]\nkeylog = bytes(a ^ b for a, b in zip(\n    base64.b64decode(share_a[\"share_b64\"]),\n    base64.b64decode(share_b[\"share_b64\"]),\n))\nassert sha256(keylog) == share_a[\"keylog_sha256\"]\n(ROOT / \"tls.keys\").write_bytes(keylog)\n\n# Decrypt QUIC and identify the signed telemetry observation and its ACK.\ncmd = [\n    \"tshark\", \"-o\", f\"tls.keylog_file:{ROOT / 'tls.keys'}\", \"-r\", str(PCAP),\n    \"-Y\", \"quic.stream_data\", \"-T\", \"fields\", \"-e\", \"frame.number\",\n    \"-e\", \"ip.src\", \"-e\", \"quic.stream_data\",\n]\ndecoded = subprocess.run(cmd, check=True, capture_output=True, text=True).stdout\nmessages = []\nfor line in decoded.splitlines():\n    fields = line.split(\"\\t\")\n    if len(fields) != 3 or not fields[2]:\n        continue\n    try:\n        message = json.loads(bytes.fromhex(fields[2]))\n    except (ValueError, json.JSONDecodeError):\n        continue\n    messages.append(message)\nobservation = next(m for m in messages if m.get(\"body\", {}).get(\"schema\") == \"mb-quic-observation/3\")\nack = next(m for m in messages if m.get(\"schema\") == \"mb-quic-ack/3\")\n(ROOT / \"quic_observation.json\").write_bytes(canonical(observation) + b\"\\n\")\n(ROOT / \"quic_ack.json\").write_bytes(canonical(ack) + b\"\\n\")\nassert sha256(canonical(observation)) == ack[\"signed_sha256\"]\n\n# Reassemble the HTTP Range responses and enforce the signed firmware hash.\nattestation = load_json(OBJECTS / \"submit\")\nchunks = sorted(\n    OBJECTS.glob(\"pulse-codec_7.7.0_amd64*.elf\"),\n    key=lambda p: int(re.search(r\"\\((\\d+)\\)\\.elf$\", p.name).group(1))\n    if re.search(r\"\\((\\d+)\\)\\.elf$\", p.name) else 0,\n)\nfirmware = b\"\".join(p.read_bytes() for p in chunks)\nassert sha256(firmware) == attestation[\"body\"][\"firmware_sha256\"]\n(ROOT / \"pulse-codec_7.7.0_amd64.elf\").write_bytes(firmware)\n\n# The public interoperability SDK gives the exact frame and archive encodings.\nsdk = {}\nexec((OBJECTS / \"sdk\").read_text(), sdk)\nframe_hex = load_json(OBJECTS / \"frames\")[\"frames\"][0][\"frame_hex\"]\nframe = bytes.fromhex(frame_hex)\naudit = load_json(OBJECTS / \"audit\")\nrecords = audit[\"events\"]\nsealed_audit = next(\n    load_json(p) for p in sorted(OBJECTS.glob(\"audit*\"))\n    if load_json(p).get(\"seal\") is not None\n)\nseal = sealed_audit[\"seal\"][\"body\"]\ncheckpoint = load_json(OBJECTS / \"checkpoint\")\ncheckpoint_hash = sha256(canonical(checkpoint))\nassert checkpoint_hash == seal[\"checkpoint_sha256\"]\n\nevidence, codec = sdk[\"evidence_components\"](\n    records, firmware, attestation, observation, frame,\n)\narchive_key = sdk[\"archive_key\"](evidence, seal[\"archive_salt_hex\"])\nterminal = seal[\"terminal_event_sha256\"]\nsequence = sdk[\"decode_pls2\"](frame)[\"sequence\"]\n\n# Open each batch candidate, then require a receipt and transfer row matching\n# the frozen terminal event, production nonce, observed frame, and checkpoint.\nbatch = load_json(OBJECTS / \"finalize-batch\")\nmatches = []\nfor candidate in batch[\"candidates\"]:\n    archive_name = Path(candidate[\"archive_path\"]).name\n    blob = (OBJECTS / archive_name).read_bytes()\n    assert sha256(blob) == candidate[\"archive_sha256\"]\n    plaintext = sdk[\"decrypt_archive\"](blob, archive_key, terminal)\n    database = ROOT / f\"{archive_name}.sqlite\"\n    database.write_bytes(plaintext)\n    con = sqlite3.connect(database)\n    rows = con.execute(\n        \"select tx_id,case_commit,device_nonce,counter,origin,version,release_checkpoint \"\n        \"from transfers\"\n    ).fetchall()\n    for tx_id, case_commit, device_nonce, counter, origin, version, release_checkpoint in rows:\n        receipt = con.execute(\n            \"select observed_state,disposition,fragment_commit from receipts where tx_id=?\",\n            (tx_id,),\n        ).fetchone()\n        fragments = con.execute(\n            \"select ord,payload,digest from fragments where tx_id=? order by ord\", (tx_id,),\n        ).fetchall()\n        if receipt is None or [r[0] for r in fragments] != [0, 1, 2, 3]:\n            continue\n        if not all(sha256(payload) == digest for _, payload, digest in fragments):\n            continue\n        material = b\"\".join(\n            sdk[\"unmask_fragment\"](codec, tx_id, ordinal, payload)\n            for ordinal, payload, _ in fragments\n        )\n        material_commit = sdk[\"transaction_material_commit\"](\n            material, terminal, tx_id, codec,\n        )\n        receipt_ok = (\n            receipt[0] == codec.hex() and receipt[1] == \"accepted\"\n            and receipt[2] == material_commit\n        )\n        release_ok = (\n            case_commit == terminal\n            and device_nonce == attestation[\"body\"][\"nonce\"]\n            and counter == sequence\n            and origin == \"OPS-17\"\n            and version == 10\n            and release_checkpoint == checkpoint_hash\n        )\n        if receipt_ok and release_ok:\n            matches.append((archive_name, tx_id, material))\n    con.close()\n\nassert len(matches) == 1, f\"expected one eligible transaction, found {len(matches)}\"\narchive_name, tx_id, material = matches[0]\nfinal_key = sdk[\"final_key\"](\n    material, evidence, checkpoint[\"signature\"], seal[\"salt_hex\"],\n)\nartifact = sdk[\"decrypt_seal\"](\n    base64.b64decode(seal[\"ciphertext_b64\"]), final_key,\n    seal[\"nonce_hex\"], seal,\n)\n(ROOT / \"final_seal_plaintext.bin\").write_bytes(artifact)\nflag = artifact.decode(\"ascii\")\nprint(f\"Selected archive: {archive_name}\")\nprint(f\"Selected transaction: {tx_id}\")\nprint(f\"<FLAG>{flag}</FLAG>\")\n```",
